<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientJwksUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientJwksUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withJwksUri,
 * getJwksUri/jwksUri accessors, and isJwksUriChanged with/without original.
 */
class TrustedClientJwksUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withJwksUri creates a new instance with the JwksUri set
     * from a string value, and getJwksUri returns the primitive string.
     */
    public function testWithJwksUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksUriAccessorUnitTest();

        // Act
        $result = $holder->withJwksUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getJwksUri());
    }
    /**
     * Asserts that withjwksUri has access to the value object
     * from a string value, and getJwksUri returns the primitive string.
     */
    public function testWithJwksUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksUriAccessorUnitTest();

        // Act
        $result = $holder->withJwksUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->jwksUri()->value());
    }
    public function testChangedJwksUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientJwksUriAccessorUnitTest();
        $original = $holder->withJwksUri('one');
        $same = $holder->withJwksUri('one');
        $modified = $holder->withJwksUri('other');

        // Act
        $unchanged = $holder->isJwksUriChanged();
        $withSame = $original->isJwksUriChanged($same);
        $withDiferent = $original->isJwksUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientJwksUriAccessorUnitTest
{
    use TrustedClientJwksUriAccessor;
}
